```csharp
private static object ProcessRelationships(
    List<Dictionary<string, object?>> rawRelationships,
    Dictionary<ulong, string> tableLookup,
    Dictionary<ulong, string> columnLookup)
{
    var relationships = new List<Dictionary<string, object?>>();

    foreach (var rel in rawRelationships)
    {
        // Get table names for filtering
        var fromTableId = rel["FromTableID"] != null ? Convert.ToUInt64(rel["FromTableID"]) : 0;
        var toTableId = rel["ToTableID"] != null ? Convert.ToUInt64(rel["ToTableID"]) : 0;

        var fromTable = tableLookup.GetValueOrDefault(fromTableId, "");
        var toTable = tableLookup.GetValueOrDefault(toTableId, "");

        // Skip auto-generated date tables
        if (fromTable.StartsWith("LocalDateTable_") || toTable.StartsWith("LocalDateTable_") ||
            fromTable.StartsWith("DateTableTemplate_") || toTable.StartsWith("DateTableTemplate_"))
            continue;

        var output = new Dictionary<string, object?>
        {
            ["from_table"] = fromTable,
            ["to_table"] = toTable,
            ["from_column"] = columnLookup.GetValueOrDefault(
                rel["FromColumnID"] != null ? Convert.ToUInt64(rel["FromColumnID"]) : 0, ""),
            ["to_column"] = columnLookup.GetValueOrDefault(
                rel["ToColumnID"] != null ? Convert.ToUInt64(rel["ToColumnID"]) : 0, ""),
        };

        if (rel["CrossFilteringBehavior"] != null)
        {
            var behavior = Convert.ToInt32(rel["CrossFilteringBehavior"]);
            output["cross_filtering"] = behavior switch
            {
                1 => "SingleDirection",
                2 => "BothDirections",
                3 => "Automatic",
                _ => "Unknown"
            };
        }

        output["is_active"] = rel["IsActive"];
        relationships.Add(output);
    }

    return relationships;
}

private static object ProcessHierarchies(
    List<Dictionary<string, object?>> rawHierarchies,
    Dictionary<ulong, string> tableLookup)
{
    var hierarchies = new List<Dictionary<string, object?>>();

    foreach (var hierarchy in rawHierarchies)
    {
        if (hierarchy["IsHidden"] != null && (bool)hierarchy["IsHidden"]!)
            continue;

        // Get table name for filtering
        var tableId = hierarchy["TableID"] != null ? Convert.ToUInt64(hierarchy["TableID"]) : 0;
        var tableName = tableLookup.GetValueOrDefault(tableId, "");

        // Skip auto-generated date hierarchies
        if (tableName.StartsWith("LocalDateTable_") || tableName.StartsWith("DateTableTemplate_"))
            continue;

        hierarchies.Add(new Dictionary<string, object?>
        {
            ["name"] = hierarchy["Name"],
            ["table"] = tableName
        });
    }

    return hierarchies;
}

private static object ProcessPartitions(
    List<Dictionary<string, object?>> rawPartitions,
    Dictionary<ulong, string> tableLookup)
{
    var partitions = new List<Dictionary<string, object?>>();

    var byTable = rawPartitions
        .GroupBy(p => {
            if (p["TableID"] == null) return "";
            var tableId = Convert.ToUInt64(p["TableID"]);
            return tableLookup.GetValueOrDefault(tableId, "");
        })
        .Where(g => !string.IsNullOrEmpty(g.Key))
        // Skip auto-generated tables
        .Where(g => !g.Key.StartsWith("LocalDateTable_") && !g.Key.StartsWith("DateTableTemplate_"));

    foreach (var tableGroup in byTable)
    {
        var modeValue = tableGroup.First()["Mode"];
        var mode = modeValue != null ? Convert.ToInt32(modeValue) : 0;

        // Convert mode enum to readable string
        var modeString = mode switch
        {
            0 => "Import",
            1 => "DirectQuery",
            2 => "Dual",
            3 => "Push",
            _ => "Unknown"
        };

        partitions.Add(new Dictionary<string, object?>
        {
            ["table"] = tableGroup.Key,
            ["mode"] = modeString
        });
    }

    return partitions;
}
```

