## What's Actually Valuable from PBIX:

**Keep these (they work and matter):**

1. **Page-level filters** - Shows default filtering strategy
   ```
   "WC_Members[Has_Active_WC_Policy] = true"
   "Years[Year] = 2026"
   ```
   This tells you what's filtered by default.

2. **Visual type distribution per page** - UI pattern recognition
   - "6 cardVisual + 1 map + 4 buttons" = Overview dashboard
   - "2 pivotTable + 1 lineChart" = Detail analysis page
   - Helps LLM understand page purpose

3. **Action button types** - Navigation patterns
   - WebUrl vs PageNavigation shows how users move around
   - External links vs internal navigation

4. **Page size consistency** - All 1280x720 = standard, good

**Kill these (unreliable/useless):**
- Per-visual field arrays (mostly empty)
- Legend positions (sparse)
- Color info (all defaults)
- The entire per-visual detail array

## Simplified PBIX Extraction

Keep the PBIX download, but extract ONLY the page summaries:

```csharp
private LayoutSummary ParseLayoutSummary(string layoutJson)
{
    var summary = new LayoutSummary();
    var visualTypeCount = new Dictionary<string, int>();

    try
    {
        using var doc = JsonDocument.Parse(layoutJson);
        var root = doc.RootElement;

        if (root.TryGetProperty("sections", out var sections))
        {
            foreach (var section in sections.EnumerateArray())
            {
                var pageSummary = ParsePageSummary(section, visualTypeCount);
                summary.Pages.Add(pageSummary);
            }
        }

        summary.TotalPages = summary.Pages.Count;
        summary.TotalVisuals = summary.Pages.Sum(p => p.VisualCount);
        summary.VisualTypeDistribution = visualTypeCount;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"      ! Warning: Error parsing layout: {ex.Message}");
    }

    return summary;
}

private PageSummary ParsePageSummary(JsonElement section, Dictionary<string, int> visualTypeCount)
{
    var pageSummary = new PageSummary();

    // Page name
    if (section.TryGetProperty("displayName", out var displayName))
        pageSummary.Name = displayName.GetString() ?? "Untitled";

    // Page size
    if (section.TryGetProperty("width", out var width) && 
        section.TryGetProperty("height", out var height))
    {
        pageSummary.PageSize = $"{width.GetDouble():F0}x{height.GetDouble():F0}";
    }

    // Page filters - KEEP THIS, IT'S USEFUL
    if (section.TryGetProperty("filters", out var filtersStr))
    {
        pageSummary.PageFilters = ParseFilters(filtersStr.GetString() ?? "[]");
    }

    // Visual containers - COUNT TYPES ONLY
    if (section.TryGetProperty("visualContainers", out var containers))
    {
        foreach (var container in containers.EnumerateArray())
        {
            var visualType = GetVisualType(container);
            if (visualType != null)
            {
                if (!visualTypeCount.ContainsKey(visualType))
                    visualTypeCount[visualType] = 0;
                visualTypeCount[visualType]++;

                if (!pageSummary.VisualTypes.ContainsKey(visualType))
                    pageSummary.VisualTypes[visualType] = 0;
                pageSummary.VisualTypes[visualType]++;

                // ONLY extract action button types (navigation patterns)
                if (visualType == "actionButton")
                {
                    var actionType = GetActionButtonType(container);
                    if (actionType != null)
                        pageSummary.ActionButtons.Add(actionType);
                }
            }
        }
    }

    pageSummary.VisualCount = pageSummary.VisualTypes.Values.Sum();

    return pageSummary;
}

private string? GetVisualType(JsonElement container)
{
    try
    {
        if (container.TryGetProperty("config", out var configStr))
        {
            var config = JsonDocument.Parse(configStr.GetString() ?? "{}");
            if (config.RootElement.TryGetProperty("singleVisual", out var singleVisual) &&
                singleVisual.TryGetProperty("visualType", out var visualType))
            {
                return visualType.GetString();
            }
        }
    }
    catch { }
    return null;
}

private string? GetActionButtonType(JsonElement container)
{
    try
    {
        if (container.TryGetProperty("config", out var configStr))
        {
            var config = JsonDocument.Parse(configStr.GetString() ?? "{}");
            if (config.RootElement.TryGetProperty("singleVisual", out var singleVisual) &&
                singleVisual.TryGetProperty("vcObjects", out var vcObjects) &&
                vcObjects.TryGetProperty("visualLink", out var visualLink))
            {
                foreach (var link in visualLink.EnumerateArray())
                {
                    if (link.TryGetProperty("properties", out var props) &&
                        props.TryGetProperty("type", out var typeExpr))
                    {
                        return ExtractLiteralValue(typeExpr);
                    }
                }
            }
        }
    }
    catch { }
    return null;
}

// Keep ParseFilters and ExtractLiteralValue helper methods
```

