private PageSummary ParsePageSummary(JsonElement section, Dictionary<string, int> visualTypeCount)
{
    var pageSummary = new PageSummary();

    // Page name
    if (section.TryGetProperty("displayName", out var displayName))
        pageSummary.Name = displayName.GetString() ?? "Untitled";

    // Page size
    if (section.TryGetProperty("width", out var width) && 
        section.TryGetProperty("height", out var height))
    {
        pageSummary.PageSize = $"{width.GetDouble():F0}x{height.GetDouble():F0}";
    }

    // Page filters - KEEP THIS, IT'S USEFUL
    if (section.TryGetProperty("filters", out var filtersStr))
    {
        pageSummary.PageFilters = ParseFilters(filtersStr.GetString() ?? "[]");
    }

    // Visual containers - COUNT TYPES ONLY
    if (section.TryGetProperty("visualContainers", out var containers))
    {
        foreach (var container in containers.EnumerateArray())
        {
            var visualType = GetVisualType(container);
            if (visualType != null)
            {
                if (!visualTypeCount.ContainsKey(visualType))
                    visualTypeCount[visualType] = 0;
                visualTypeCount[visualType]++;

                if (!pageSummary.VisualTypes.ContainsKey(visualType))
                    pageSummary.VisualTypes[visualType] = 0;
                pageSummary.VisualTypes[visualType]++;

                // ONLY extract action button types (navigation patterns)
                if (visualType == "actionButton")
                {
                    var actionType = GetActionButtonType(container);
                    if (actionType != null)
                        pageSummary.ActionButtons.Add(actionType);
                }
            }
        }
    }

    pageSummary.VisualCount = pageSummary.VisualTypes.Values.Sum();

    return pageSummary;
}

private string? GetVisualType(JsonElement container)
{
    try
    {
        if (container.TryGetProperty("config", out var configStr))
